    }

    /**
     * 예약이 없으면 아무 일도 하지 않는다(빈 Optional). 예약이 있으면 맨 앞 예약자만 빌릴 수 있고,
     * 맨 앞 예약자라면 예약을 소진시켜 돌려준다.
     */
    public Optional<Reservation> fulfillFor(UUID memberId) {
        if (waiting.isEmpty()) {
            return Optional.empty();
        }
        Reservation first = waiting.get(0);
        if (!first.getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(bookId);
        }
        first.fulfill();
        waiting.remove(0);
        return Optional.of(first);
    }

    public List<Reservation> waiting() {
        return List.copyOf(waiting);
    }
}

