    public ReservationPersistenceAdapter(ReservationJpaRepository reservationJpaRepository) {
        this.reservationJpaRepository = reservationJpaRepository;
    }

    @Override
    public void saveReservation(Reservation reservation) {
        // 새 예약은 INSERT, 기존 예약은 소진 여부만 갱신한다. 줄 순서(seq)를 유지하려고 엔티티를 새로 만들지 않는다.
        reservationJpaRepository.findByReservationId(reservation.getId())
                .ifPresentOrElse(entity -> entity.updateFulfilled(reservation.isFulfilled()),
                        () -> reservationJpaRepository.save(reservationMapper.toEntity(reservation)));
    }

    @Override
    public List<Reservation> loadActiveReservations(UUID bookId) {
        return reservationJpaRepository.findByBookIdAndFulfilledFalseOrderBySeqAsc(bookId).stream()
                .map(reservationMapper::toDomain)
                .toList();
    }
}
