void discarding_a_book_on_loan_returns_409_with_book_on_loan() throws Exception {
    String bookId = registerBook("Borrowed Book");
    loanBook(bookId, registerMember());
    mockMvc.perform(post("/loans/{loanId}/return", loanId))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.loanId").value(loanId))
